74	 */
75	
76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    private final HouseholdDuplicateValidator householdDuplicateValidator;
90	
91	    private final PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector;
92	
93	    private final NamesakeCounter namesakeCounter;
94	
95	    private final HouseholdSizeCounter householdSizeCounter;
96	
97	    private final HouseholdMembershipLevelCap householdMembershipLevelCap;
98	
99	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
100	
101	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
102	
103	    private final OwnerAuditLogger ownerAuditLogger;
104	
105	    private final WelcomeNotifier welcomeNotifier;
106	
107	    private final MemberIdDeduplicator memberIdDeduplicator;
108	
109	    private final IdempotentOwnerCreationStore idempotentOwnerCreationStore;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 HouseholdDuplicateValidator householdDuplicateValidator,
116	                                 PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector,
117	                                 NamesakeCounter namesakeCounter,
118	                                 HouseholdSizeCounter householdSizeCounter,
119	                                 HouseholdMembershipLevelCap householdMembershipLevelCap,
120	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
121	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
122	                                 OwnerAuditLogger ownerAuditLogger,
123	                                 WelcomeNotifier welcomeNotifier,
124	                                 MemberIdDeduplicator memberIdDeduplicator,
125	                                 IdempotentOwnerCreationStore idempotentOwnerCreationStore) {
126	        this.clinicService = clinicService;
127	        this.ownerMapper = ownerMapper;
128	        this.petMapper = petMapper;
129	        this.visitMapper = visitMapper;
130	        this.householdDuplicateValidator = householdDuplicateValidator;
131	        this.possibleDuplicateOwnerDetector = possibleDuplicateOwnerDetector;
132	        this.namesakeCounter = namesakeCounter;
133	        this.householdSizeCounter = householdSizeCounter;
134	        this.householdMembershipLevelCap = householdMembershipLevelCap;
135	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
136	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
137	        this.ownerAuditLogger = ownerAuditLogger;
138	        this.welcomeNotifier = welcomeNotifier;
139	        this.memberIdDeduplicator = memberIdDeduplicator;
140	        this.idempotentOwnerCreationStore = idempotentOwnerCreationStore;
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
146	        Collection<Owner> owners;
147	        if (lastName != null) {
148	            owners = this.clinicService.findOwnerByLastName(lastName);
149	        } else {
150	            owners = this.clinicService.findAllOwners();
151	        }
152	        if (owners.isEmpty()) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
171	        Optional<Owner> replay = replayForIdempotencyKey(idempotencyKey);
172	        if (replay.isPresent()) {
173	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replay.get()), HttpStatus.OK);
174	        }
175	        Owner owner = createOwner(ownerFieldsDto);
176	        rememberForIdempotencyKey(idempotencyKey, owner);
177	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
178	        HttpHeaders headers = new HttpHeaders();
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    /** Validate, derive and persist a brand-new owner from the submitted fields. */
185	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
186	        normalizeAddress(ownerFieldsDto);
187	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
190	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
191	        DisposableEmailDomainValidator.validate(owner.getEmail());
192	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
193	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
194	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
195	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
196	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
197	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
198	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
199	            // Reject only a true duplicate (an owner identical to one already on file); a distinct
200	            // new household member is allowed but flagged as a possible duplicate. A declared member
201	            // bypasses this block, and is not a suspected duplicate.
202	            this.householdDuplicateValidator.rejectIfDuplicate(owner);
203	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
204	                .ifPresent(owner::setPossibleDuplicateOf);
205	        }
206	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
207	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
208	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
209	        owner.setMembershipLevelCap(this.householdMembershipLevelCap.ceilingFor(owner.getHouseholdId()));
210	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
211	        String memberId = MemberIdGenerator.generate(IdentityRegion.of(region), owner.getTelephone(),
212	            owner.getLastName(), owner.getRegistrationDate());
213	        owner.setMemberId(this.memberIdDeduplicator.deduplicate(memberId));
214	        this.clinicService.saveOwner(owner);
215	        this.ownerAuditLogger.logCreated(owner);
216	        this.welcomeNotifier.enqueueWelcome(owner);
217	        return owner;
218	    }
219	
220	    /** The owner originally created for this idempotency key, if the key has already been seen. */
221	    private Optional<Owner> replayForIdempotencyKey(String idempotencyKey) {
222	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
223	            return Optional.empty();
224	        }
225	        return this.idempotentOwnerCreationStore.findOwnerId(idempotencyKey)
226	            .map(this.clinicService::findOwnerById);
227	    }
228	
229	    /** Remember the created owner so a repeat with the same idempotency key replays it. */
230	    private void rememberForIdempotencyKey(String idempotencyKey, Owner owner) {
231	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
232	            this.idempotentOwnerCreationStore.remember(idempotencyKey, owner.getId());
233	        }
234	    }
235	
236	    /**
237	     * Normalize the submitted address fields and resolve the effective {@code address}. The
238	     * structured lines are normalized in place; when a non-blank {@code addressLine1} is supplied it
239	     * takes precedence and {@code address} is composed from the normalized lines, otherwise the flat
240	     * {@code address} input is normalized and kept for backward compatibility.
241	     */
242	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
243	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
244	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
245	        ownerFieldsDto.setAddressLine1(line1);
246	        ownerFieldsDto.setAddressLine2(line2);
247	        if (line1 != null && !line1.isBlank()) {
248	            ownerFieldsDto.setAddress(AddressNormalizer.compose(line1, line2));
249	        } else {
250	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
251	        }
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
257	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
258	        if (currentOwner == null) {
259	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	        }
261	        currentOwner.setAddress(ownerFieldsDto.getAddress());
262	        currentOwner.setCity(ownerFieldsDto.getCity());
263	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
264	        currentOwner.setLastName(ownerFieldsDto.getLastName());
265	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
266	        this.clinicService.saveOwner(currentOwner);
267	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
268	    }
269	
270	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
271	    @Transactional
272	    @Override
273	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
274	        Owner owner = this.clinicService.findOwnerById(ownerId);
275	        if (owner == null) {
276	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	        }
278	        this.clinicService.deleteOwner(owner);
279	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
280	    }
281	
282	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
283	    @Override
284	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
285	        Owner owner = this.clinicService.findOwnerById(ownerId);
286	        if (owner == null) {
287	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
288	        }
289	        HttpHeaders headers = new HttpHeaders();
290	        Pet pet = petMapper.toPet(petFieldsDto);
291	        owner.setId(ownerId);
292	        pet.setOwner(owner);
293	        pet.getType().setName(null);
294	        this.clinicService.savePet(pet);
295	        PetDto petDto = petMapper.toPetDto(pet);
296	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
297	            .buildAndExpand(pet.getId()).toUri());
298	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
299	    }
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
304	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
305	        if (currentOwner != null) {
306	            Pet currentPet = this.clinicService.findPetById(petId);
307	            if (currentPet != null) {
308	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
309	                currentPet.setName(petFieldsDto.getName());
310	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
311	                this.clinicService.savePet(currentPet);
312	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
313	            }
314	        }
315	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
316	    }
317	
318	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
319	    @Override
320	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
321	        HttpHeaders headers = new HttpHeaders();
322	        Visit visit = visitMapper.toVisit(visitFieldsDto);
323	        Pet pet = new Pet();
324	        pet.setId(petId);
325	        visit.setPet(pet);
326	        this.clinicService.saveVisit(visit);
327	        VisitDto visitDto = visitMapper.toVisitDto(visit);
328	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
329	            .buildAndExpand(visit.getId()).toUri());
330	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
331	    }
332	
333	
334	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
335	    @Override
336	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
337	        Owner owner = this.clinicService.findOwnerById(ownerId);
338	        if (owner != null) {
339	            Pet pet = owner.getPet(petId);
340	            if (pet != null) {
341	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
342	            }
343	        }
344	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
345	    }
346	}
