package org.springframework.samples.petclinic.rest.notification;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.stereotype.Component;

/**
 * Enqueues the welcome notification for a newly created owner by emitting a line to the
 * dedicated {@code NOTIFY} logger, keeping notification dispatch decoupled from the audit
 * trail and the application's diagnostic logging.
 */
@Component
public class WelcomeNotifier {

    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    /**
     * Enqueues a welcome notification for the given owner, recording its id and member id.
     *
     * @param owner the persisted owner (must already have an assigned id)
     */
    public void enqueueWelcome(Owner owner) {
        NOTIFY.info("Welcome notification enqueued: ownerId={} memberId={}",
            owner.getId(), owner.getMemberId());
    }
}

